def test_inverse_any_tag_and_shared_reading_scope(tmp_path): database = ArchiveDatabase.create(tmp_path / "synthetic-inverse.db") reference = utcnow() with database.write() as session: session.add_all([Artist(id=i, pixiv_user_id=str(i), name=f"artist{i}") for i in (1, 2)]) session.add_all([Work(id=i, pixiv_illust_id=str(i), artist_id=1 if i < 3 else 2, title=str(i), type="illust", posted_at=reference, downloaded_at=reference) for i in range(1, 5)]) session.add_all([WorkTag(work_id=1, tag="A"), WorkTag(work_id=2, tag="A"), WorkTag(work_id=2, tag="B"), WorkTag(work_id=3, tag="B")]) session.add(LocalPreference(work_id=3, is_hidden=True)) session.add(RemoteBookmark(work_id=2, value=True, source="readback", confirmed_at=reference, version=1)) app = FastAPI() app.include_router(create_router(lambda: SimpleNamespace(library=Library(database)))) with TestClient(app) as client: > assert client.get("/api/library").json()["total"] == 3 # includes work 4 without tags ^^^^^^^^^^^^^^^^^^^^^^^^^^
